def load(p):return json.loads(Path(p).read_text())
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def csvrows(p):
 with Path(p).open() as f:return list(csv.DictReader(f))
def write(p,v):
 p=Path(p);p.parent.mkdir(parents=True,exist_ok=True)
 p.write_text(json.dumps(v,indent=2,ensure_ascii=False,allow_nan=False)+'\n' if not isinstance(v,str) else v.rstrip()+'\n')
def csvwrite(p,rr):
 with Path(p).open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rr[0]),lineterminator='\n');w.writeheader();w.writerows(rr)
def qualifies(mid,m):return m['correct']*100>=62*m['n'] and mid not in EXCLUDED and not m['archival']
def main_view(all_s):
 keep=[mid for mid in all_s['ranked_model_ids'] if qualifies(mid,all_s['models'][mid])]
 return {**all_s,'models':{mid:all_s['models'][mid] for mid in keep},'ranked_model_ids':keep,'main_model_ids':keep}
def archive():
 if (ARCHIVE/'manifest.json').exists():
  for entry in load(ARCHIVE/'manifest.json')['files'].values():assert sha(ARCHIVE/entry['path'])==entry['sha256']
  return
 head=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip();files={}
 for name in PRESERVE:
  raw=subprocess.check_output(['git','show',head+':'+name],cwd=ROOT);assert raw==(ROOT/name).read_bytes(),'Overlapping presentation change: '+name
  path=ARCHIVE/(name+'.snapshot');path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(raw);files[name]={'path':name+'.snapshot','sha256':sha(path)}
 write(ARCHIVE/'manifest.json',dict(commit=head,scope='Exact presentation and source bytes before System1v2; dated releases unchanged',files=files))
def table(headers,records,attrs=None):
 esc=lambda v:html.escape(str(v));body=[]
 for i,row in enumerate(records):
  attr='' if attrs is None else ' '+attrs[i]
  body.append('<tr'+attr+'>'+''.join('<td>'+esc(v)+'</td>' for v in row)+'</tr>')
 return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(v)+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join(body)+'</tbody></table></div>'
def mdtable(headers,records):
 clean=lambda v:str(v).replace('|','\\|').replace('\n',' ')
 return '| '+' | '.join(headers)+' |\n| '+' | '.join('---' for _ in headers)+' |\n'+''.join('| '+' | '.join(clean(v) for v in row)+' |\n' for row in records)
