 if dest!=SOURCE:
  for name in INPUTS:shutil.copyfile(SOURCE/name,dest/name)
 write(dest/'statistics.json',s);csvwrite(dest/'model_statistics.csv',list(s['models'].values()));csvwrite(dest/'category_scores.csv',cats)
